 11→export interface PastJob {
 12→  id: string;
 13→  title: string | null;
 14→  job_description: string;
 15→  status: string;
 16→  created_at: string;
 17→  resume_count: number;
 18→  jd_analysis_json: any;
 19→  dynamic_weights_json: Record<string, number> | null;
 20→  inbox_email: string | null;
 21→}
 22→
 23→export interface Result {
 24→  id: string;
 25→  resume_id: string;
 26→  overall_score: number;
 27→  missing_skills: string[];
 28→  summary: string | null;
 29→  interview_questions: any;
 30→  filename: string;
 31→  file_path: string | null;
 32→  candidate_name: string | null;
 33→  candidate_email?: string | null;
 34→  candidate_phone?: string | null;
 35→  candidate_location?: string | null;
 36→  // Dynamic scoring fields
 37→  hard_fit?: boolean;
 38→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
 39→  confidence?: number;
 40→  strengths_json?: string[];
 41→  gaps_json?: string[];
 42→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string };
 43→  matched_must_haves?: string[];
 44→  missing_must_haves?: string[];
 45→  scoring_version?: string;
 46→  pending?: boolean;
 47→}
 48→
 49→export interface ExistingResume {
 50→  id: string;
 51→  filename: string;
 52→  file_path: string | null;
 53→  candidate_name: string | null;
 54→  created_at: string;
 55→}
 56→
 57→const Index = () => {
 58→  const { user } = useAuth();
 59→
 60→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 61→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 62→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 63→  const [results, setResults] = useState<Result[]>([]);
 64→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 65→  const [authOpen, setAuthOpen] = useState(false);
 66→
 67→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 68→
 69→  const fetchPastJobs = useCallback(async () => {
 70→    if (!user) return;
 71→    setLoadingPastJobs(true);
 72→    try {
 73→      const { data: jobs } = await supabase
 74→        .from("jobs")
 75→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
 76→        .eq("user_id", user.id)
 77→        .order("created_at", { ascending: false })
 78→        .limit(50);
 79→      if (jobs) {
 80→        setPastJobs(jobs.map((j: any) => ({
 81→          id: j.id,
 82→          title: j.title,
 83→          job_description: j.job_description,
 84→          status: j.status,
 85→          created_at: j.created_at,
 86→          resume_count: j.resumes?.[0]?.count ?? 0,
 87→          jd_analysis_json: j.jd_analysis_json,
 88→          dynamic_weights_json: j.dynamic_weights_json,
 89→          inbox_email: j.inbox_email ?? null,
 90→        })));
 91→      }
 92→    } catch (err) {
 93→      console.error("Failed to load past jobs:", err);
 94→    } finally {
 95→      setLoadingPastJobs(false);
 96→    }
 97→  }, [user]);
 98→
 99→  useEffect(() => {
100→    fetchPastJobs();
101→  }, [fetchPastJobs]);
102→
103→  const loadJobData = async (jobId: string) => {
104→    setSelectedJobId(jobId);
105→    try {
106→      const [resumesRes, resumeListRes] = await Promise.all([
107→        supabase
108→          .from("resumes")
109→          .select("id, filename, file_path, candidate_name, created_at")
110→          .eq("job_id", jobId)
111→          .order("created_at", { ascending: false }),
112→        supabase
113→          .from("resumes")
114→          .select("id, filename, file_path, candidate_name, parsed_json")
115→          .eq("job_id", jobId),
116→      ]);
117→
118→      const resumes = resumesRes.data ?? [];
119→      setExistingResumes(resumes);
120→
121→      const resumeData = (resumeListRes.data ?? []) as Array<{
122→        id: string;
123→        filename: string;
124→        file_path: string | null;
125→        candidate_name: string | null;
126→        parsed_json?: any;
127→      }>;
128→      if (resumeData.length === 0) {
129→        setResults([]);
130→        return;
131→      }
132→
133→      const resumeIds = resumeData.map((r) => r.id);
134→      const { data: resultData } = await supabase
135→        .from("results")
136→        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
137→        .in("resume_id", resumeIds);
138→
139→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
140→      const merged: Result[] = (resultData ?? []).map((r: any) => {
141→        const resume = resumeMap.get(r.resume_id);
142→        const parsed = resume?.parsed_json as any;
143→        return {
144→          ...r,
145→          overall_score: r.overall_score ?? 0,
146→          missing_skills: r.missing_skills ?? [],
147→          filename: resume?.filename ?? "Unknown",
148→          file_path: resume?.file_path ?? null,
149→          candidate_name: resume?.candidate_name ?? null,
